local byID, byName

-- Parsed once, the first time anything asks. Eighteen thousand records
-- come through gmatch in well under a frame, and the string is let go
-- afterwards since the tables now hold everything it said.
function Items.Load()
    if byID then return byID end
    byID, byName = {}, {}
    if raw then
        for id, name, q, class, sub, icon, ilvl, req, inv in
            raw:gmatch("(%d+)\t([^\t\n]*)\t(%d+)\t(%d+)\t(%d+)\t(%d+)\t(%d+)\t(%d+)\t(%d+)\n")
        do
            id = tonumber(id)
            icon = tonumber(icon)
            byID[id] = {
                id         = id,
                name       = name,
                quality    = tonumber(q),
                classID    = tonumber(class),
                subclassID = tonumber(sub),
                icon       = (icon and icon > 0) and icon or nil,
                ilvl       = tonumber(ilvl),
                minLvl     = tonumber(req),
                slot       = tonumber(inv),    -- Enum.InventoryType; 0 for nothing worn
            }
            byName[#byName + 1] = { lower = name:lower(), id = id, name = name }
        end
        raw = nil
    end
    table.sort(byName, function(a, b)
        if a.name == b.name then return a.id < b.id end
        return a.name < b.name
    end)
    return byID
end

function Items.Get(id)
    id = tonumber(id)
    return id and Items.Load()[id] or nil
end

function Items.Count()
    return Items.count
end

-- Every item there is, in name order. The list is shared, so callers
-- read it and do not write to it.
function Items.All()
    Items.Load()
    local out = {}
    for i, entry in ipairs(byName) do out[i] = entry.id end
    return out
end

-- Every item whose name contains the needle, in name order. Plain
-- substring, case-insensitive, the way the search box already behaves
-- against the met list.
function Items.Search(needle)
    Items.Load()
    needle = (needle or ""):lower()
    local out = {}
    if needle == "" then return out end
    for _, entry in ipairs(byName) do
        if entry.lower:find(needle, 1, true) then
            out[#out + 1] = entry.id
        end
    end
    return out
end
